<script setup lang="ts">import {computed,ref} from 'vue';import type {PairedResult,PairedReplication} from '../types/domain';import {number,signed} from '../utils/format';const props=defineProps<{result:PairedResult}>();const baselineFirst=ref(true);function orient(row:PairedReplication,swapped:boolean):PairedReplication{if(!swapped)return row;return {...row,difference_minutes:-row.difference_minutes,baseline_mean_wait_minutes:row.candidate_mean_wait_minutes,candidate_mean_wait_minutes:row.baseline_mean_wait_minutes,baseline_p_wait:row.candidate_p_wait,candidate_p_wait:row.baseline_p_wait,baseline_busy_fraction:row.candidate_busy_fraction,candidate_busy_fraction:row.baseline_busy_fraction,baseline_arrivals:row.candidate_arrivals,candidate_arrivals:row.baseline_arrivals}}const swaps=computed(()=>!baselineFirst.value);const ordered=computed(()=>props.result.paired.replications.map(r=>orient(r,swaps.value)));const left=computed(()=>swaps.value?props.result.paired.mean_candidate_wait_minutes:props.result.paired.mean_baseline_wait_minutes);const right=computed(()=>swaps.value?props.result.paired.mean_baseline_wait_minutes:props.result.paired.mean_candidate_wait_minutes);const leftWindows=computed(()=>swaps.value?props.result.candidate.windows:props.result.baseline.windows);const rightWindows=computed(()=>swaps.value?props.result.baseline.windows:props.result.candidate.windows);const meanDiff=computed(()=>swaps.value?-props.result.paired.mean_difference_minutes:props.result.paired.mean_difference_minutes);const ci=computed<[number,number]>(()=>{const [lo,hi]=props.result.paired.difference_ci95;return swaps.value?[-hi,-lo]:[lo,hi]});
</script><template><div class="paired-board"><div class="paired-switch"><label><input type="checkbox" v-model="baselineFirst"/>基准侧在左（取消勾选交换两侧，逐次差值反号）</label><span>{{result.paired.replications.length}}次共用同一批到达与服务的配对重复</span></div><div class="paired-metrics"><div><small>左侧 {{leftWindows}} 窗口 · 平均等待</small><b>{{number(left)}}</b><em>分钟 · 同批到达与服务</em></div><div><small>右侧 {{rightWindows}} 窗口 · 平均等待</small><b>{{number(right)}}</b><em>分钟 · 同批到达与服务</em></div><div class="featured"><small>逐次配对差值均值</small><b>{{signed(meanDiff)}}</b><em>分钟 · 左 − 右</em></div><div><small>差值95%区间</small><b class="range">{{signed(ci[0])}} — {{signed(ci[1])}}</b><em>分钟 / 配对差值的正态近似</em></div></div><div class="difference-note"><span>{{swaps?'当前显示按“左 − 右”排列，交换后逐次差值反号；归档与接口保存的定义为“基准 − 候选”。':result.paired.difference_definition}}</span><small>区间只含同一批随机流下的窗口效应</small></div><div class="table-scroll"><table class="paired-table"><thead><tr><th>重复</th><th>{{leftWindows}}窗口 平均等待</th><th>{{rightWindows}}窗口 平均等待</th><th>差值 / 分钟</th><th>{{leftWindows}}窗口 等待概率</th><th>{{rightWindows}}窗口 等待概率</th><th>到达数</th></tr></thead><tbody><tr v-for="r in ordered" :key="r.replication"><td>{{r.replication}}</td><td>{{number(r.baseline_mean_wait_minutes)}}</td><td>{{number(r.candidate_mean_wait_minutes)}}</td><td><b :class="['diff',{negative:r.difference_minutes<0}]">{{signed(r.difference_minutes)}}</b></td><td>{{(r.baseline_p_wait*100).toFixed(1)}}%</td><td>{{(r.candidate_p_wait*100).toFixed(1)}}%</td><td>{{r.baseline_arrivals}} / {{r.candidate_arrivals}}</td></tr></tbody></table></div></div></template>
<style scoped>.paired-board{margin-bottom:26px}.paired-switch{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding:12px 0;font-size:10px;color:var(--muted)}.paired-switch label{display:flex;gap:8px;align-items:center;font-size:10px}.paired-switch input{width:auto}.paired-metrics{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:6px 0 0}.paired-metrics>div{padding:18px 14px;border-right:1px solid var(--line)}.paired-metrics>div:last-child{border:0}.paired-metrics .featured{background:var(--green);color:var(--paper)}.paired-metrics .featured small{color:oklch(78% .035 130)}.paired-metrics small{font-size:9px}.paired-metrics b{display:block;font-size:30px;font-weight:400;font-family:'ZCOOL XiaoWei';margin:15px 0 10px}.paired-metrics b.range{font-size:23px}.paired-metrics em{font-size:9px;font-style:normal;color:var(--muted)}.paired-metrics .featured em{color:oklch(78% .035 130)}.difference-note{display:flex;gap:18px;justify-content:space-between;font-size:10px;color:var(--muted);padding:12px 2px;flex-wrap:wrap}.paired-table td b.diff{font-weight:500}.paired-table td b.negative{color:oklch(52% .12 45)}@media(max-width:1150px){.paired-metrics{grid-template-columns:repeat(2,1fr)}.paired-metrics>div{border-bottom:1px solid var(--line)}}@media(max-width:767px){.paired-metrics b{font-size:25px}.paired-metrics b.range{font-size:19px}.paired-metrics>div{padding:15px 11px}}</style>
